import { l, type Class9Chapter, type Class9Task, type ChoiceTask, type L, type ModelTask } from './types';

const base = (prompt: L, context: L) => ({ prompt, context,
  success: l('This record meets the stated check. Explain its evidence and limits to your teacher.', 'यह रिकॉर्ड बताई जाँच पूरी करता है। टीचर को इसके प्रमाण और सीमाएँ समझाएँ।'),
  correction: l('The submitted record is incorrect. Recheck the supplied data and the rule for each field before testing again.', 'जमा किया रिकॉर्ड गलत है। फिर जाँचने से पहले दिए डेटा और हर फ़ील्ड का नियम दोबारा देखें।'),
  hint: l('Work only from the fictional records supplied here. Keep training examples, validation/test records and unknown facts separate.', 'केवल यहाँ दिए काल्पनिक रिकॉर्ड से काम करें। ट्रेनिंग उदाहरण, वैलिडेशन/टेस्ट रिकॉर्ड और अज्ञात तथ्य अलग रखें।') });
const choice = (prompt: L, context: L, options: [string,L,L][], correct: string): ChoiceTask => ({...base(prompt,context),kind:'choice',options:options.map(([id,label,feedback])=>({id,label,feedback})),correct});
const select = (prompt: L, context: L, items: [string,L,L][], expected: string[]): Class9Task => ({...base(prompt,context),kind:'select',items:items.map(([id,label,feedback])=>({id,label,feedback})),expected});
const match = (prompt:L,context:L,rows:[string,L,string,L][],options:[string,L][]):Class9Task=>({...base(prompt,context),kind:'match',rows:rows.map(([id,label,answer,explanation])=>({id,label,answer,explanation})),options:options.map(([id,label])=>({id,label}))});
const numbers=(prompt:L,context:L,fields:[string,L,number,L][]):Class9Task=>({...base(prompt,context),kind:'number',fields:fields.map(([id,label,answer,explanation])=>({id,label,answer,explanation,min:0}))});
const scene=(title:L,caption:L,dialogue:L)=>({title,caption,dialogue});
